        # None (no pre-release) sorts after any pre-release
        if pre1 is None and pre2 is None:
            return 0
        if pre1 is None:
            return 1
        if pre2 is None:
            return -1

        # Compare identifiers left to right
        for i in range(min(len(pre1), len(pre2))):
            id1 = pre1[i]
            id2 = pre2[i]

            # Check if identifiers are all digits
            is_digit1 = id1.isdigit()
            is_digit2 = id2.isdigit()

            if is_digit1 and is_digit2:
                # Both numeric: compare numerically
                num1 = int(id1)
                num2 = int(id2)
                if num1 < num2:
                    return -1
                elif num1 > num2:
                    return 1
            elif is_digit1:
                # Only id1 is numeric: numeric sorts before non-numeric
                return -1
            elif is_digit2:
                # Only id2 is numeric: numeric sorts before non-numeric
                return 1
            else:
                # Both non-numeric: compare by ASCII order
                if id1 < id2:
                    return -1
                elif id1 > id2:
                    return 1

        # If all shared identifiers are equal, fewer identifiers sorts first
        if len(pre1) < len(pre2):
            return -1
        elif len(pre1) > len(pre2):
            return 1
        return 0

    def sort_key(v):
        major, minor, patch, prerelease = parse_version(v)

        # Create a sort key tuple
        # For pre-release comparison, we need a special approach
        # We'll return a tuple that naturally sorts correctly
        if prerelease is None:
            # No pre-release: sort after any pre-release of same version
            prerelease_key = (1,)  # 1 means no pre-release
        else:
            # Has pre-release: sort before any without pre-release
            # Convert identifiers to a comparable form
            converted = []
            for identifier in prerelease:
                if identifier.isdigit():
                    # Numeric: (0, number) so it sorts before non-numeric
                    converted.append((0, int(identifier)))
                else:
                    # Non-numeric: (1, string) so it sorts after numeric
                    converted.append((1, identifier))
            prerelease_key = (0, tuple(converted))

        return (major, minor, patch, prerelease_key)

    # Use stable sort to maintain input order for equal precedence
    return sorted(versions, key=sort_key)

